-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95034] = { "Il debito", "Parla con Lumina Windsinger alla ⟦Sepulcher=Mausolea⟧.", "Credo che tu debba sapere che non sono stati davvero gli gnoll ad attaccarci sulla strada.\n\nIn realtà ci ha attaccati una creatura gigantesca, simile a un lupo, che ora so chiamarsi \"worgen\". Ha fatto fuori le nostre guardie ed è venuta verso di me, ma Banon si è gettato sul suo cammino. Sono riuscita a lanciare un incantesimo che ha spaventato la creatura e l'ha messa in fuga, ma Banon era già stato morso gravemente. Insisteva perché lo lasciassi lì, ma mi sono rifiutata.\n\nStavamo tornando qui zoppicando quando ci hanno trovati gli gnoll. Ciò che è successo dopo è stato terrificante...", nil, "Ora capisci. Allo stremo delle forze, dopo essere stato trafitto da una dozzina di lame gnoll, si è sollevato per colpirmi. In quell'ultimo istante i nostri sguardi si sono incrociati, e ho capito che sapeva ancora chi era e che mi riconosceva. Sapeva cosa stava succedendo, ma non aveva alcun controllo su se stesso. Quella è stata la parte peggiore.\n\nSe una cosa simile è possibile, vedrò morta la creatura che lo ha condannato, così che non possa mai più infliggere quest'orrore a un altro essere vivente. Lo giuro sul cielo sopra di noi.", 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, 0xb4f8e463, "...m." },
  [95036] = { "Una lama baciata dalla luna", "Parla con Trevan Rol alla ⟦Sepulcher=Mausolea⟧ e portagli i materiali che gli servono.", "Trevan mi dice che i worgen sono una grave minaccia per gli abitanti della ⟦Silverpine Forest=Selva Pinargento⟧. Nonostante la loro forza e resistenza possono essere uccisi, ma ce n'è uno in particolare che, per una magia sconosciuta, sembra non restare mai morto.\n\nÈ quello che ci ha attaccati. È noto come Old Fire-Eye ed è il più grosso e il più crudele della sua specie. Per abbatterlo ci servirà un'arma speciale.\n\nParla con Trevan: ti darà un elenco di ciò che serve per forgiare un'arma simile.", "Affidati alla Luce perché guidi la tua lama. Ma la Luce ha bisogno di una buona lama da guidare.", "Ora che abbiamo i materiali che ci servono, ci manca solo un fabbro che forgi la lama per noi. E credo di conoscere proprio il fabbro giusto.", 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, 0x1c7078a4, 0xf4085685, "....." },
  [95041] = { "Accumulatori di dati", "Raccogli 7 Gnomeregan Archival Data nei dintorni di Gnomeregan, poi consegnali a Jemma Quikswitch a ⟦Ironforge=Forgiardente⟧.", "Prima di fuggire da Gnomeregan ho fatto una copia cartacea degli archivi di famiglia. Equazioni di campo arcanotecniche, progetti di scafi di sottomarini della Seconda Guerra, la ricetta del chili di nonna Quikswitch... le nostre più grandi conquiste sono in quei file.\n\nSolo una volta a ⟦Ironforge=Forgiardente⟧ ho scoperto un buco nello zaino! Mancano diverse schede perforate e, senza di loro, i dati sono troppo confusi per recuperarli.\n\nLe schede devono essere sepolte nella neve, da qualche parte fuori da Gnomeregan. Potresti trovarle? Lo so, è un tentativo disperato...", "Come procede il recupero dei dati?", "Queste schede sembrano un po' umide... ma posso lavorarci! Grazie, {name}!", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "Alla ricerca della Gemma Kor", "Porta una Gemma Kor a Ulric Frostveil a ⟦Ashenvale=Valtetra⟧.", "<Un/Una> <paladino/paladina> dei Reietti... qui a ⟦Ashenvale=Valtetra⟧? Divertente.\n\nQuindi cerchi una Gemma Kor? Non mi sorprende: a volte i paladini dell'⟦Alliance=Alleanza⟧ le usano per potenziare armi e strumenti magici. Perché <un/una> <paladino/paladina> <caduto/caduta> come te dovrebbe essere diverso?\n\nSe desideri davvero una di queste gemme, devi andare a nord, nelle rovine note come ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. I naga che usano ancora le gemme si trovano là sotto. Non andare da sol<o/a>, {class}.", "Le gemme Kor possono servire a grandi atti di malvagità. Non sta a me giudicare se le tue intenzioni sono pure. A me non importa.", "Avrai senz'altro notato la corruzione che permea questa gemma. Per i tuoi scopi, la magia necessaria a dissipare il male che le streghe naga vi hanno infuso è piuttosto semplice. Un vero peccato: si potrebbe imparare molto da poteri simili.\n\nNon è che saresti dispost<o/a> ad abbandonare qualunque missione ti abbia spinto a cercare questa gemma, e a vendermela invece? Potrebbe rivelarsi preziosa per le mie... ricerche accademiche.", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95065] = { "È ora di pescare", "Porta $N1 ⟦Shiny Bauble=Esca Lucente⟧ e $N2 Nightcrawlers a Gilbert Gray, al porto di ⟦Stormwind=Roccavento⟧.", "Che vista... Il meglio che un vecchio possa chiedere.\n\nI pesci abboccano eccome, adesso, ma mi è rimasta solo l'ultima esca. Non è che hai con te dell'attrezzatura da pesca in più? Ma certo che no, perdonami. Mi entusiasmo così tanto all'idea di lanciare un'altra lenza che non mi è venuto in mente che forse sono uno dei pochi a portarsi dietro l'attrezzatura ovunque vada.\n\nPotresti aiutarmi a rifornirmi? Catherine Leland ha un assortimento di articoli da pesca appena a ovest del ⟦Trade District=Quartiere del Commercio⟧, lungo i canali. Dille che ti manda il vecchio Gray.", "Hai preso l'attrezzatura da pesca?", "Tempismo perfetto! Ne ho preso uno grosso con l'ultima esca. Finora è una gran giornata. Qui abboccano davvero!\n\nFacciamo così: visto che sei stat<o/a> così gentile da tenere in attività questo vecchio, che ne dici di qualche pesce per il viaggio?", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95111] = { "Un talento sottovalutato", "Parla con Ott e chiedigli di forgiare la tua lama.", "Al ⟦Tarren Mill=Mulino di Tarren⟧ c'è un fabbro d'armi di nome Ott. A detta di tutti è un fabbro qualunque, che vende lame semplici ai viaggiatori. Io stesso ho comprato una spada da lui e, quando qualche tempo dopo l'ho portata a Sepulcra per la manutenzione, i fabbri di lì sono rimasti sorpresi dalla sua qualità. Pensavano che venisse da un celebre mastro fabbro, ma no: era soltanto Ott.\n\nVorrei dare a questo orco l'occasione di fare qualcosa di davvero speciale. Porta i materiali a Ott, al ⟦Tarren Mill=Mulino di Tarren⟧, e offrigli la commissione.", "Ti serve una lama, {class}?", "Interessante. Non credo che qualcuno mi abbia mai chiesto di eseguire una commissione su misura. Di solito faccio solo armi umili e funzionali, a modo mio. Non è granché, ma è un lavoro onesto e non cerco riconoscimenti né gloria.\n\nSono felice di provarci, ma perché sei venut<o/a> da me per questo? A ⟦Undercity=Sepulcra⟧ ci sono tanti fabbri che accetterebbero lavori su misura come questo.", 0x2c5a8af0, 0x57d2ed34, 0x9137acf7, 0x45d644e4, 0xc6b81f00, "....." },
  [95125] = { "Il capolavoro di Ott", "Guarda Ott mentre forgia la tua lama.", "Sono materiali davvero pregiati, {class}. Mi onori lasciandomi forgiare questa lama per te, e spero solo di essere all'altezza delle tue aspettative.\n\nTi prego, fatti indietro, così posso cominciare la forgiatura.", nil, "Questa lama è il mio lavoro migliore e spero che ti serva bene nei tuoi viaggi. Grazie ancora per questa occasione.\n\nAka'Magosh, amic<o/a>.", 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, 0xee452c14, "...m." },
  [95126] = { "La Moonsilver Blade", "Porta Ott's Masterwork a Trevan Rol nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Ecco la lama. Hai detto che ti ha mandato un paladino di nome Trevan? Quando lo rivedrai, ringrazialo da parte mia per questa occasione. Va' con onore, amic<o/a>.", "Ott è riuscito a portare a termine la commissione?", "<Trevan prende la lama e la esamina con cura.>\n\nAndrà benissimo, {name}. Sapevo che Ott era capace di creare qualcosa di davvero grande.\n\nOra non resta che uccidere quella bestia. Parla con Lumina quando sei pront<o/a>.", 0x774c6075, 0xb9d5e27a, 0xac0b5a01, 0xaf39b5e9, 0x469d97a1, "....." },
  [95140] = { nil, "Usa la Moonsilver Blade per distruggere Old Fire-Eye nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Vedo che ora hai la tua arma, {class}. Prego che non ti tradisca.\n\nLa gente del posto dice che Old Fire-Eye caccia in un'ampia zona a sud di qui e che di solito lo si trova vicino ai cancelli di Gilneas. Trovalo e usa la tua nuova lama per farla finita con lui. Quando avrai finito, torna e avrai la gratitudine dei Windshaper.", "È fatta? La bestia è morta?", "Grazie, {name}. Ora Banon può riposare in pace.\n\nSe me lo permetti, credo di poter infondere nella tua lama, appena bagnata di sangue, una piccola parte della magia del mio popolo.\n\n<Gli occhi di Lumina Windsinger cominciano a brillare di un azzurro vivido mentre tocca la lama insanguinata che hai in mano.>\n\nÈ fatto. È poca cosa, e difficilmente potrei migliorare una lama così magnifica. In ogni caso, pregherò i venti perché ti serva bene, {class}.", 0x1db24010, 0xee598827, 0x2f1bb8e0, 0x95a43f2e, 0xb76eccca, "e...." },
  [95161] = { "Ricorda che ti voglio bene", "Consegna la Blood-Stained Letter ad Avette Fellwood a ⟦Duskwood=Boscovespro⟧.", "Se cerchi Jeremy Heartweaver, la cosa migliore è parlare con la sua nuova madre adottiva, Avette Fellwood, giù a ⟦Duskwood=Boscovespro⟧. Una donna dolce. Probabilmente le serve un altro paio di mani per il suo lavoro, ma è sempre meglio che restare all'orfanotrofio.\n\nSe vedi il piccolo Jeremy, digli che pensiamo tutti a lui, d'accordo?", "Sì? Di cosa hai bisogno?", "Oh, no...\n\nÈ gentile da parte tua portarmela, ma non credo che Jeremy sia pronto a vederla. La direttrice Nightingale ha detto che il mio piccolo Jeremy non parla più dall'attacco a Lordaeron, e non intendo forzarlo adesso. Mostrargliela gli causerebbe solo altro dolore.\n\nNon guardarmi così. Non gli nasconderò il suo passato, ma ha bisogno di tempo per guarire. Gliela darò quando sarà più grande. Grazie di essere passat<o/a>, ma credo sia ora che tu vada.", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95189] = { nil, "Riporta il Crest of Lordaeron a Lady Dena Kennedy a ⟦Stormwind City=Roccavento⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Stormwind=Roccavento⟧ sarebbe molto ansioso di metterci le mani sopra.>", nil, nil, 0x98ec1516, 0xea3f7a39, 0x6f2a4873, nil, nil, "e..mm" },
  [95195] = { nil, "Raccogli $N1 Bloodied Insignia e portale al generale Marcus Jonathan a ⟦Stormwind City=Roccavento⟧.", "<La vecchia insegna dell'⟦Alliance=Alleanza⟧ sembra essere appartenuta a un soldato di Lordaeron. Queste rovine sono probabilmente piene di medaglie simili, che i parenti ancora in vita sarebbero grati di riavere.>", "Sembri portare un pesante fardello, {name}. Di che si tratta?", "Il tuo istinto di portarmele non era infondato. Quando Lordaeron cadde sotto il Flagello, molti fuggirono per rifugiarsi qui a ⟦Stormwind=Roccavento⟧. Probabilmente ne restano pochi che possano reclamare di persona queste insegne.\n\nIl tuo servizio a ⟦Stormwind=Roccavento⟧ merita un encomio, {name}. Comincerò subito a consegnare questi pegni ai parenti più stretti.", 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "e...." },
  [95204] = { nil, "Porta il Crest of Lordaeron a Oran Snakewrithe a ⟦Undercity=Sepulcra⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Undercity=Sepulcra⟧ sarebbe molto ansioso di metterci le mani sopra.>", "Che cos'hai lì, {class}? Un bocconcino gustoso?", "<Oran morde lo stemma per accertarne l'autenticità.>\n\nGuarda un po'. Un'autentica reliquia della nostra patria. Quasi intatta, per giunta. Con questa dovremo stare molto attenti.\n\nGrazie per averci aiutato a restaurare la nostra storia, {class}. Mi assicurerò che ne abbiamo cura.", 0x98ec1516, 0x937c7b4b, 0x992e7722, 0x059931e7, 0xc46da411, "e...." },
  [95212] = { "Sulle selle non si risparmia", "Raccogli 6 Pristine Leopard Pelt e consegnale alla ⟦Amberstill Ranch=Tenuta di Ambraquieta⟧.", "Ci stiamo preparando a mandare una squadra di arieti a rinforzare la spedizione di Alterac, ma abbiamo finito il materiale per fare le selle.\n\nRaccogli le pelli dei leopardi più grossi e feroci a est e portamele. Lassù fa un freddo pungente, e le nostre truppe meritano solo le pelli migliori per tenersi al caldo!", "Hai l'aria infreddolita, {class}. Come va la caccia?", "Queste pelli diventeranno selle eccellenti. Hai reso onore all'⟦Alliance=Alleanza⟧, {class}!", 0x07df31f7, 0x270babaf, 0xb5c3ab85, 0x545929d0, 0xcdcfccf7, "....." },
  [95213] = { nil, "Porta l'Empty Powder Keg al capocava Thesten, alla ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Sul barile c'è un timbro:\n\nPOLVERE ESPLOSIVA - PERICOLO - NON MANEGGIARE - PERICOLO - SOLO CON AUTORIZZAZIONE DEL CAPOCAVA - PERICOLO\n\nHai la brutta sensazione che i trogg non dovrebbero averla. Sarebbe meglio avvisare la cava al più presto.", "Che cos'hai lì?", "<Il nano impallidisce quando vede il barile vuoto.>\n\n...Dove l'hai trovato?", 0x8848eca5, 0xd56ef55e, 0xf1f411df, 0xac2369a3, 0x28899f23, "e...." },
  [95214] = { nil, "Recupera $N1 Stolen Blasting Powder dai trogg a est della ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧, poi torna dal capocava Thesten.", "Questo barile conteneva abbastanza polvere da trasformare la sala del trono di re Magni in un cortile a cielo aperto. Dobbiamo recuperarla dai trogg prima che capiscano come accenderla.", "Spero che tu abbia buone notizie per me.", nil, 0x8848eca5, 0x4fe59366, 0xcc857a5c, 0xb50481e8, nil, "e...m" },
  [95216] = { "La nuova piaga", "Preleva la Highly Toxic Strain da Witherfang nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ per Theodore Griffs, a ⟦Undercity=Sepulcra⟧.", "Benvenut<o/a> nell'organo più vitale di ⟦Undercity=Sepulcra⟧: l'Apothecarium! Qui sperimentiamo sui più virulenti tra gli esemplari esotici di Azeroth.\n\nSono di buon umore, perciò ti metterò a parte della mia ultima indagine. Pare che un artropode particolarmente velenoso si aggiri tra le rovine sopra la nostra bella città. Si dice che le sue tossine corrodano persino la carne dei non morti. Che cosa elettrizzante!\n\nVoglio verificare queste voci. Se dovessi trovarti a deperire per il suo morso, mi piacerebbe tanto averne un campione.", "Qualunque sciocco ti dirà che il metodo di trasmissione più efficace passerà sempre per il sangue.\n\nDevo vedere questo ceppo con i miei occhi!", "L'hai ucciso??\n\nHmpf. Per tua fortuna, questo icore dovrebbe bastare per ricostruirne le proprietà. Non ti conviene metterti contro la Royal Apothecary Society.\n\nSparisci dalla mia vista!", 0xbf7a7e24, 0xec263960, 0x9214d563, 0x5c8c63f0, 0x8f9e0d7b, "....." },
  [95217] = { "Il fabbro della cava", "Raccogli 12 Lingotto di Rame e 4 Toughened Boar Hide e consegnali a Frast Dokner.", "Quindi vuoi imparare il mestiere del fabbro? Forse possiamo aiutarci a vicenda.\n\nIl carico di rifornimenti è in ritardo e mi servono materiali per qualche riparazione all'accampamento. Se mi procuri quello che mi serve, ti insegnerò alcune delle mie tecniche. Ti sembra giusto?", "Non battere la fiacca, {name}. Fare il fabbro non è roba da pigri!", "Sei una persona piena di risorse, {name}.\n\nOra ascoltami bene: non ho intenzione di ripetermi!", 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, 0x8461c8b8, 0x9e396b99, "....." },
  [95250] = { "Creature abominevoli", "Recupera la Head of the Baron nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ e riportala al capitano Truman.", "Che vuoi, {race}? Non vedi che c'è una guerra da vincere?\n\nIl mio padrone si è già lanciato nella mischia e mi ha ordinato di restare al mio posto. Però è passato parecchio tempo.\n\nDubito che sopravvivresti dieci minuti in combattimento, ma se serve a tenere occupata la tua mente semplice, perché non vai a cercare il gran maresciallo? È l'eroe più alto e statuario su cui tu abbia mai posato gli occhi. Lo riconoscerai quando lo vedrai.", nil, nil, 0x83266151, 0xb8e0ac06, 0x0f67af09, nil, nil, "...mm" },
  [95314] = { "Quell'elisir verde di Shadowvale", "Raccogli $N1 Bottle of Whispering Elixir a Shadowvale, poi torna da Carolai Anise a Brill.", "Prima dell'invasione del Flagello, l'isolato villaggio di Shadowvale era noto per il suo Whispering Elixir. Distillato da erbe che si trovano solo a Tyr's Fall, l'elisir era ricercato da speziali, mistici e avvelenatori, anche dopo essere stato bandito in città.\n\nHo ricevuto richieste da diversi compratori ansiosi di mettere le mani su un po' di elisir. Raggiungi le rovine di Shadowvale, nel profondo della Whispering Forest, a ovest. Offro un compenso considerevole se riesci a recuperarne qualche bottiglia per me.", "Confido che tu non ti sia pers<o/a>?", "Dici che a Shadowvale c'è del male? Ammetto che non mi sorprende. La gente della foresta era un tipo strano e non amava i visitatori. Alcuni credono che la Whispering Forest stessa sia maledetta e che l'elisir distillato dalle sue radici porti con sé la stessa maledizione...\n\n...ma basta con superstizioni e dicerie, {name}. Grazie per gli elisir. Ecco, prendi questo come pagamento.", 0x62c6b7bf, 0xff6777a1, 0x5740e013, 0x46ba8900, 0x23664c51, "....." },
  [95328] = { nil, "Consegna Whispering Horror Residue a padre Lankester, nel ⟦War Quarter=Quartiere della Guerra⟧ di ⟦Undercity=Sepulcra⟧.", "Contro ogni buonsenso, raschi via e raccogli i resti ancora contorti della bestia. Qualcuno a ⟦Undercity=Sepulcra⟧ potrebbe trovarli utili.", "Hai qualcosa per me, {class}?", nil, 0xb283ff1d, 0xa13a9b4c, 0x1336682a, 0xcbd58f92, nil, "e...m" },
  [95349] = { "L'Earthen Ring", "Prendi la nave skycutter da Zephras Isle a Mulgore e, all'arrivo, parla con Alaana Stormwalker.", "I recenti eventi legati al culto hanno ritardato i miei piani di viaggio verso Azeroth, e per un po' devo restare qui a Valanaar. Tu e una manciata di altri Windshaper sarete invece la nostra avanguardia. Alaana Stormwalker accoglierà i nostri Windshaper al loro arrivo a Mulgore, e ti invito a esplorare Azeroth mentre noi concludiamo i nostri affari qui. Presto vi raggiungeremo.\n\nQuando sarai pront<o/a>, raggiungi il molo appena fuori da questa loggia e sali sulla nave skycutter che troverai lì.\n\nBanu-Alah, {name}.", nil, "Altri avventurieri da Zephras, vedo. Magnifico. I venti sono davvero dalla nostra parte! Ci vorrà un po' di tempo per stabilirci qui, quindi potresti approfittarne per esplorare questa nuova terra.\n\nAzeroth è un mondo nuovo ed emozionante, ma è anche un mondo pericoloso. Faresti bene a prepararti a questa nuova avventura conoscendo le terre qui vicino.", 0x28da0b16, 0x74e6dafa, 0x76858aa9, nil, 0xde8ad8f1, "...m." },
  [95350] = { "Benvenuti su Azeroth", "Raggiungi Orgrimmar e parla con Thrall nella Valle della Saggezza.", "Quaggiù il mondo è grande, e i nostri nuovi alleati sono la chiave della nostra sopravvivenza.\n\nL'Earthen Ring fa parte dell'\"⟦Horde=Orda⟧\", una fiera unione di popoli affini. La vicina città di ⟦Thunder Bluff=Picco del Tuono⟧ appartiene all'⟦Horde=Orda⟧, e più a est si trova la capitale, Orgrimmar.\n\nCerca il maestro di volo al centro di ⟦Thunder Bluff=Picco del Tuono⟧. Ti porterà in volo a Orgrimmar, dove prenderai contatto con il Capoguerra dell'⟦Horde=Orda⟧, Thrall, a nome dei Windshaper. Che i venti ti guidino, {name}.", nil, "Lok-tar, {class}. Sono Thrall, Capoguerra dell'⟦Horde=Orda⟧.\n\nUn messaggero dell'Earthen Ring mi ha detto di aspettarmi dei membri dei Windshaper, ed eccoti qui. Non mi sarei aspettato di trovarmi davanti uno degli alti elfi, qui a Orgrimmar, ma l'⟦Horde=Orda⟧ ti accoglierà comunque come suo ospite.\n\nHai la mia benedizione per viaggiare attraverso le terre dell'⟦Horde=Orda⟧. Va' con onore, Windshaper.", 0x2f003d6f, 0x53ee86b6, 0x7024f167, nil, 0x328b0c81, "...m." },
  [95384] = { nil, "Porta la pergamena incompleta a Dudd Fizzlescroll, alla ⟦Booty Bay=Baia del Bottino⟧.", "<Gli strani simboli sulla pergamena magica ti confondono. Anche se non conosci la lingua in cui è scritta, non avverti al suo interno forze particolarmente instabili. Forse un collezionista di magie bizzarre saprebbe che farsene.>", nil, nil, 0xec99fcec, 0xa76f397b, 0x819e84fc, nil, nil, "e..mm" },
  [95494] = { "Orgoglio ferito e pelli di leone", "Raccogli 6 Savannah Lion Hide dalle Savannah Matriarch e dai Savannah Patriarch nelle ⟦Barrens=Savane⟧.", "Mi serve qualcuno con un braccio forte per la spada e un po' di tempo libero, che mi aiuti a raccogliere delle pelli di leone. Mi brucia l'orgoglio chiedere un aiuto simile a un estraneo, ma di recente mi sono ferito a una gamba. Finché non guarisco non sono in condizione di andare a caccia, ma ho degli impegni da rispettare.\n\nDi solito i più grossi di questa zona hanno le pelli migliori, quindi comincia da quelli.", "Come va la caccia?", nil, 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, 0xe02b27bb, nil, "....m" },
  [95495] = { "Il conciatore eremita", "Porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ all'eremita sulla cresta che domina i Colli Aridi, nelle ⟦Barrens=Savane⟧.", "Queste pelli sono destinate a un conciatore con cui commercio spesso. È una specie di eremita e vive da solo in cima alla cresta alle mie spalle. In questo momento non riesco ad arrampicarmi facilmente su un pendio così ripido, quindi ti sarei debitore se potessi fare tu la consegna.\n\nAh, a proposito dell'... aspetto di questo conciatore. Non c'è da allarmarsi. Nonostante l'apparenza, non è una minaccia. Te lo giuro.", "Salute, {class}. Cosa ti porta quassù, nella mia proprietà, oggi?", nil, 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, 0xbe27a510, nil, "....m" },
  [95507] = { "La selvaggina di Vrang", "Raccogli 8 Trapped Game dagli Sprung Trap nelle ⟦Barrens=Savane⟧.", "Già che sei là fuori, mi saresti di grande aiuto se dessi un'occhiata alle mie trappole. Le ho sparse per tutta la valle.\n\nRiportami la piccola selvaggina che ho catturato. Però tieni d'occhio gli altri animali. Questa zona può essere pericolosa, se non stai attent<o/a>.", nil, nil, 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, nil, nil, "...mm" },
  [95508] = { "Ospiti sgraditi", "Aiuta Walton a sopravvivere allo scontro con Terry Longdrink e i fanti di marina di Kul Tiras.", "Sì, un tempo ero nella marina di Kul Tiras. Dopo che il lord ammiraglio prese Theramore e cominciò la sua campagna in Durotar, avevo... delle \"obiezioni\" sui suoi metodi. Soprattutto su quelli che prevedevano di giustiziare i civili.\n\nLa storia è più lunga, ma... aspetta... cos'è quello?\n\nC'è un gruppo di uomini che sale lungo la cresta!", nil, "Be', a quanto pare siamo tutti vivi. Io... sapevo che un giorno questa storia mi avrebbe raggiunto. Ti sono debitore per l'aiuto di oggi.\n\nTi prego, prendi questo. Non è molto, ma è il minimo che possa fare.\n\nBuon viaggio, {class}.", 0xaedbb4a0, 0xfb874c5b, 0x5b6957f0, nil, 0xd4531345, "...m." },
  [95534] = { "Il mistero di Strahnbrad", "Risolvi il mistero di Strahnbrad e riferisci ciò che hai scoperto in paese, a ⟦Hillsbrad=Colletorto⟧.", "<Il biglietto è bruciacchiato in alcuni punti, ma ancora leggibile.>\n\nSi dice che quei vecchi mantici abbiano una volontà propria e prendano vita quando nessuno guarda. Non m'importa se è una storia di fantasmi: farai meglio a venirne a capo prima del mio ritorno.\n\nA Strahnbrad c'è un grande potere, lo so.\n\n< Il resto del biglietto è bruciato e strappato, come se fosse stato colpito da una magia del fuoco. >", nil, nil, 0x84d1d4cf, 0xe5975afe, 0x53e7de0b, nil, nil, "...mm" },
  [95621] = { "Guai nella valle", "Raggiungi la carovana distrutta e scopri di più sul perché i Kul Tirani sono qui.", "Stamattina ho visto un gruppo di umani che cercava qualcosa nella valle qui sotto. Sono riuscito a guardarli meglio con il mirino del fucile, ed era chiaro che erano soldati con le insegne di Kul Tiras.\n\nSe sei dispost<o/a> a lavorare per me, raggiungi il punto in cui questi soldati si sono accampati, vicino alla carovana distrutta a sud. Uccidi tutti quelli che trovi e cerca di scoprire perché sono qui.", "Ciò che resta della flotta di Daelin Proudmoore, che ancora ne innalza lo stendardo, è marcio e barbaro quanto lo era l'ammiraglio prima di morire.\n\nNon so perché siano così lontani da Tiragarde, ma non può essere niente di buono.", nil, 0x389c29a3, 0xef54682f, 0xcaabc078, 0xdcde325c, nil, "....m" },
  [95646] = { "Orrori sull'altopiano", "Uccidi un Highland Horror negli Excavation Sites e porta il suo nucleo radicale a Rethiel the Greenwarden, nelle ⟦Wetlands=Paludi Grigie⟧.", "Queste paludi salmastre custodiscono una riserva più grande delle acque dolci del sud. Mi addolora, eppure nelle mie radici sento una corruzione che filtra da quella gola di montagna.\n\nLe creature, come quelle delle nostre terre basse, reagiscono con più asprezza alla contaminazione. Prive fin dall'alba della vita del sale che tempra il mare, hanno poca forza contro un simile male.\n\nVa' su quegli altopiani e portami il nucleo radicale dell'Highland Horror.", nil, nil, 0x79650957, 0x81ee8465, 0xbce12a7e, nil, nil, "...mm" },
  [95647] = { "Perso nella boscaglia", "Trova Ardin Grassman negli Excavation Sites.", "Mio marito, Ardin, ha un raro dono per percepire la natura. Si arrampica su qualsiasi vetta per raccogliere le erbe e i fiori che mi servono per l'alchimia, e così i nostri scaffali e la dispensa restano sempre pieni.\n\nMa temo che si sia cacciato nei guai. È passata di qui una squadra di scavo in cerca di provviste. Tra le altre cose, parlavano di erbe altissime, diverse da qualsiasi cosa avessero mai visto. Mi ha detto che doveva andare a vederle con i suoi occhi. È via da troppo tempo!\n\nSe scopri qualcosa su di lui, te ne sarò grata.", nil, nil, 0xc3371e69, 0x4d0fc432, 0x6d7c1497, nil, nil, "...mm" },
  [95663] = { "Voci sulle Fauci di Drago", "Raggiungi le ⟦Wetlands=Paludi Grigie⟧ e incontra l'agente degli Inseguitori della Morte sulle colline sopra l'accampamento delle Fauci di Drago.", "Le Fauci di Drago sono un clan temibile.\n\nSono noti per una magia vincolante abbastanza forte da piegare i draghi al loro servizio, e si dice che stiano preparando una dimostrazione di questo potere nelle ⟦Wetlands=Paludi Grigie⟧. Che sia verità o millanteria, gli ⟦Deathstalkers=Inseguitori della Morte⟧ non possono agire su sussurri appena abbozzati. Dei simboli corrotti non mi hanno detto altro.\n\nUn'agente degli ⟦Deathstalkers=Inseguitori della Morte⟧ ha bisogno di una mano sulle colline sopra l'accampamento delle Fauci di Drago. Raggiungila lì. Ti rivelerà i prossimi passi.", nil, nil, 0xecfb9de3, 0x607aac05, 0x19f544b5, nil, nil, "...mm" },
  [95664] = { "Il sapere degli antichi", "Porta la Titan Relic all'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧, e cerca qualcuno che possa dirti di più al riguardo.", "Questo insolito frammento composito diffonde la luce come un prisma vivente. La sua natura è incerta, ma il suo potere sembra antico. Le menti più esperte di manufatti di quell'epoca remota devono trovarsi sull'Altura degli Anziani, a ⟦Thunder Bluff=Picco del Tuono⟧.", nil, nil, 0x1d764e46, 0x4a860375, 0xd36a8f92, nil, nil, "...mm" },
  [95682] = { "Aprire le fauci", "Uccidi le forze delle Fauci di Drago negli Excavation Sites e torna dall'agente degli Inseguitori della Morte, all'esterno, con tutto ciò che recuperi.", "Fauci di Drago. <Si lascia sfuggire uno sbuffo secco e divertito.>\n\nQuel che resta del clan dei domatori di draghi crede di aver trovato qualcosa che potrebbe riportarlo al potere di un tempo. Agli occhi di chi... del loro falso Capoguerra?\n\nSpazza via quel clan raffazzonato dagli Excavation Sites, così che i nostri ⟦Deathstalkers=Inseguitori della Morte⟧ possano entrare senza essere scoperti.\n\nSe le Fauci di Drago hanno addosso qualcosa di interessante, portalo a me: queste informazioni devono restare tra noi e il nostro comando reale.", nil, nil, 0x01716485, 0x9fb46d83, 0x5cd87c72, nil, nil, "...mm" },
  [95697] = { "Gusti che cambiano", "Entra negli Excavation Sites, nelle ⟦Wetlands=Paludi Grigie⟧, e riporta della Thicket Raptor Meat.", "Zamja dice che ci serve più cucina casereccia.\nSe cominciamo a vendere carne di raptor, secondo lei attirerà clienti che di solito non passano dal Borstan's Firepit.\n\nNon è una cattiva idea. Ma io voglio qualcosa che vada oltre i sapori dei nostri villaggi natii. Siamo a Orgrimmar! Borstan dovrebbe servire una versione grandiosa dei loro piatti preferiti di sempre.\n\nUn cacciatore è appena tornato dalle ⟦Wetlands=Paludi Grigie⟧ con un artiglio gigante dei raptor della boscaglia degli Excavation Sites.\n\nTi va un lavoretto?", nil, nil, 0xefd7f8a7, 0x406ca9c2, 0xc77dbee9, nil, nil, "...mm" },
  [95737] = { "In cerca di Caitlin", "Parla con Caitlin Grassman al ⟦Menethil Harbor=Porto di Menethil⟧.", "Ogni tanto scrivo ad altri del mio mestiere: erboristi o eccentrici che studiano piante rare e curiosità locali. Ci scambiamo scoperte, e a volte avvertimenti su ciò che ci aspetta.\n\nUn'alchimista delle ⟦Wetlands=Paludi Grigie⟧ mi ha scritto di una squadra di scavo di cui faceva parte suo marito, che aveva trovato tracce di un'erba primordiale perduta da tempo... ma non mi ha mai fatto sapere se fosse abbondante o facile da raggiungere.\n\nSe puoi, va' a vedere come sta Caitlin Grassman al ⟦Menethil Harbor=Porto di Menethil⟧.", nil, nil, 0xf6e09b80, 0x29283070, 0xb0744041, nil, nil, "...mm" },
  [95748] = { "Le antiche leggende dei Gurubashi", "Usa la pelle e il carboncino per ricavare un calco della tavoletta della terza leggenda troll.", "Strano. Questo pezzo di tavoletta che mi hai portato parla della città perduta di I'lalai come di una civiltà vasta e sterminata. Ma le rovine al largo della scogliera non sono abbastanza grandi per qualcosa di quelle dimensioni.\n\n{name}, a nord della Scogliera Infame, sulle colline lungo la costa, c'è un'antica rovina troll. Al suo interno c'è una tavoletta che contiene le leggende della città troll perduta. Desidero studiare meglio questa leggenda.\n\nPrendi questa pelle e questo carboncino e ricava un calco della tavoletta, poi torna da me.", nil, nil, 0x1163f14b, 0x8eb3fa59, 0x85f90475, nil, nil, "...mm" },
  [95770] = { "Sulle tracce della città perduta", "Esplora la Scogliera Infame e trova l'ingresso della caverna.", "Dopo aver riletto la leggenda, non sembra che stiamo cercando la città perduta nel posto sbagliato, ma forse c'è ancora qualche dettaglio che ci è sfuggito.\n\nDa giovane mi immergevo tra le rovine della Scogliera Infame, ma era prima che vi si stabilissero i murloc. Se la memoria non m'inganna, laggiù c'era una caverna.\n\nHo sentito che ora in quella zona si stanno radunando dei naga, cosa insolita. Voglio sapere che cosa li ha attirati lì.\n\nVa' a esplorare appena a ovest della Scogliera Infame e torna da me con qualunque notizia.", nil, nil, 0xbfc53c6c, 0x5befc8cb, 0xba46d29c, nil, nil, "...mm" },
  [95771] = { "Un assaggio di oscurità", nil, nil, nil, nil, 0x8583a882, nil, nil, nil, nil, ".mmmm" },
  [95772] = { "Alla ricerca di Songblade", "Cerca Daewyn, il fratello di Dorin Songblade, agli ⟦Whelgar's Excavation Site=Scavi di Whelgar⟧.", "Mio fratello ha provato a trascinarmi nelle ⟦Wetlands=Paludi Grigie⟧ con una squadra di scavo partita da Loch Modan. Diceva che andavano su colline dove nessun nano ha mai messo piede, per non so che scavi.\n\nEh, ci sarei pure andato, se non fossi già in ritardo con 'sta pila di cinture da sistemare.\n\nDi solito, però, Daewyn scrive quando parte. Non ho saputo niente, e stavolta ho una brutta sensazione.\n\nSe vai da quelle parti, ti spiace dare un'occhiata a mio fratello?", nil, nil, 0x4225ee40, 0x72145fde, 0x91fbce45, nil, nil, "...mm" },
  [95773] = { "Nemici nell'acqua", "Raccogli $N1 Brinescale Trident dai Brinescale Skirmisher.", "{class}, arrivi al momento giusto. Ho appena ricevuto nuovi rapporti su un'attività dei naga proprio al largo della nostra costa. Sembra che sciamino attorno ad alcune vecchie rovine troll vicino al fondale.\n\nSiamo già allo stremo per difenderci dagli Scalporosso della zona e dagli ogre che saccheggiano le nostre carovane. Non possiamo permetterci un attacco a sorpresa dal mare.\n\nVa' e uccidine quanti più puoi, e portami i loro tridenti come prova del tuo successo.", nil, nil, 0xf6a51353, 0x23c1e22b, 0xbd430784, nil, nil, "...mm" },
  [95774] = { "Il suo nome è Olgra", "Uccidi i verrospini e raccogli $N1 Olgra's Adornments per il memoriale di Mankrik.", "Chi mi ha guarito non è riuscito a salvare lei, ed è morta in battaglia. Il suo nome è Olgra, e non la dimenticherò mai.\n\nNon hai trovato i suoi ornamenti sul corpo? Portava molti gioielli d'osso levigato.\n\nUccidi i Razormane Raider vicino al punto in cui è caduta e trova le sue preziose opere d'arte!\n\nLi metterò accanto al memoriale che sto costruendo in sua memoria.", "Ora mi restano solo i ricordi, ma costruirò un tributo a Olgra perché non svaniscano mai.", "Metterò questi ornamenti accanto al memoriale di mia moglie, così da non dimenticarla mai. Il mio sangue ribollirà sempre di vendetta!\n\nHai fatto a me... a noi... un grande favore, {name}.", 0xe0733c23, 0x64b2ed87, 0x1085cf6b, 0xcb32b1fe, 0x22fd675b, "....." },
  [95775] = { "La Drowned City", "Usa la pelle e il carboncino per ricavare i calchi delle tavolette che trovi nella Drowned City.", "Ciò che sto per chiederti non è un'impresa da poco, {class}, e probabilmente ti serviranno alleati forti per riuscirci.\n\nVoglio saperne di più sulle rovine dall'altra parte della caverna sorvegliata dai naga. Se i miei sospetti si rivelano fondati, potrebbe davvero trattarsi della città perduta di I'lalai. La quantità di sapere storico perduto a portata di mano potrebbe essere senza pari, ma sono troppo vecchio per avventurarmi di persona.\n\nEntra nelle rovine e ricava i calchi delle tavolette che trovi, poi torna da me.", nil, nil, 0x7b66254a, 0xda9d19e9, 0xf184a1b6, nil, nil, "...mm" },
  [95776] = { "L'unico Brinescale buono...", "Uccidi Var'Taka nella Drowned City.", "Hai fatto bene a uccidere i naga al largo della nostra costa, ma il fatto che siano nelle nostre acque in così gran numero significa che c'è una minaccia ancora più grande.\n\nHo parlato con Kin'weelay, e lui pensa che questi naga Brinescale si stiano infiltrando nelle rovine della Drowned City. Se i naga sono lì, non tramano niente di buono e probabilmente stanno cercando qualcosa.\n\nNon possiamo permettere che mettano le mani su qualcosa che potrebbe comprometterci qui, ed è ora di porre fine a tutto questo. Uccidi il loro capo e torna da me.", nil, nil, 0x6893b9a2, 0x0ab0d353, 0xee8da360, nil, nil, "...mm" },
  [95787] = { "Due dosi, con acqua", "Usa la pelle e il carboncino per ricavare i calchi delle tavolette che trovi nella Drowned City.", "<Le mani del custode della sapienza Dibbs tremano mentre legge il rapporto di ricognizione e le leggende troll.>\n\nPossibile? Da questo resoconto sembra che la città troll perduta di I'lalai sia riemersa proprio al largo della costa di Rovotorto! Dobbiamo indagare subito. Ebbene, se le mie ricerche sono corrette, questa potrebbe essere la scoperta archeologica del secolo!\n\nTi prego, so che il viaggio fino a Rovotorto è lungo, ma se ti trovi nella Drowned City, raccogli tutte le leggende che trovi e riportamele.", nil, nil, 0x8a52ce4a, 0xda9d19e9, 0xfa014234, nil, nil, "...mm" },
  [95788] = { "Le magie della Drowned City", "Raccogli $N1 I'lalai Fetish dai troll della Drowned City.", "I feticci dei Fendicranio che fratello Nimetz ti ha affidato sono davvero potenti, anche se non credo abbiano contribuito alle condizioni di Kurzen, o almeno non direttamente.\n\nTuttavia, se le voci sono vere e la città troll perduta di I'lalai è davvero risorta dalla sua tomba d'acqua, è possibile che le magie oscure usate per sollevare la città maledetta siano collegate.\n\nSe osi avventurarti nella Drowned City di I'lalai, raccogli tutti i feticci troll che trovi e portali qui da me perché possa studiarli.", nil, nil, 0xe9ed0635, 0xd05a8a60, 0xcb7fb810, nil, nil, "...mm" },
  [95795] = { "Caduto nella palude", "Torna da Dorin Songblade.", "<Copri il corpo del nano con il suo mantello.>\n\nVa' a ⟦Lakeshire=Borgolago⟧ e informa di persona Dorin Songblade di ciò che è accaduto a suo fratello negli Excavation Sites.", nil, nil, 0xbfc85885, 0x2739cdb1, 0x9e5ae38b, nil, nil, "...mm" },
  [95803] = { "Un pegno di buona fede", "Porta la testa di Rudolph Gelhardt a Sylvanas Windrunner, a ⟦Undercity=Sepulcra⟧.", "Ora che abbiamo preso la testa del comandante caduto in disgrazia, devi consegnarla a ⟦Undercity=Sepulcra⟧. Sylvanas Windrunner diffida molto di noi, e ci disprezza quasi apertamente.\n\nConsegna la testa di Rudolph Gelhardt alla Dama Oscura. Dimostrale che sappiamo mettere ordine in casa nostra e che siamo devoti alla prosperità dei Reietti.", "Perché ti rivolgi a me, {class}?", "Non dubito della sincerità di Danitha né del suo desiderio di guadagnare un posto tra i Reietti per quelli come te. Tuttavia, sospetto che non sarà l'ultima volta che vedremo uno dei tuoi fratelli e delle tue sorelle impazzire e rivolgere la Luce contro il proprio popolo.\n\nPotrebbe venire il momento in cui deciderò che tollerare il tuo ordine sciagurato non è più nell'interesse dei Reietti. Ti suggerisco di continuare a servire la tua gente con diligenza.\n\nVi terremo d'occhio.", 0x8a963535, 0x09f1d511, 0x27427458, 0x2d8b7e5f, 0x2b29670e, "....." },
  [95805] = { "La grazia di An'she e Mu'sha", "Porta lo Smoldering Incense al santuario di An'she e Mu'sha, sulle colline a sud-est, prima che l'incenso si riduca in cenere in dieci minuti!", "Il sole e la luna, An'she e Mu'sha, non fanno parte del nostro mondo come gli elementi, eppure la loro luce ci dà vita, guida e speranza.\n\nRendiamo omaggio agli spiriti del mondo, e così rendiamo omaggio anche ai gemelli.\n\nSe vuoi mostrare il tuo rispetto, prendi questo incenso fumante e portalo a un santuario sulle colline a sud-est, che domina la mesa, a sud dei verrospini. Fa' presto, così da raggiungere il santuario prima che l'incenso si consumi.\n\nNon bagnarlo!", "<Il fumo dell'incenso sale verso il cielo.>", "<Mentre versi l'incenso nel fuoco, il profumo si diffonde attorno a te, lasciandoti solo il sacchetto vuoto e un sottile senso di appagamento.>", 0x1483f5df, 0x82228fe2, 0x52a83811, 0xd4bc4ea6, 0xd28f1b93, "....." },
  [95809] = { "Intrecciato col cuore", "Torna da Caitlin Grassman al ⟦Menethil Harbor=Porto di Menethil⟧.", "Mi serve un momento di riposo prima di trovare da solo la strada per uscire.\n\n<Tira fuori dalla sacca alcune canne, le intreccia e le piega rapidamente a forma di cuore.>\n\nPrendi questo e portalo a Caitlin. Dille che tornerò presto a casa! Ora che grazie a te c'è un sentiero libero, raccoglierò i miei fasci e seguirò le tue tracce.\n\nGrazie.", nil, nil, 0x7c49eff3, 0xb6ab7769, 0x84c0de8c, nil, nil, "...mm" },
  [95810] = { "Il trasporto della reliquia perduta", "Porta la Titan Relic al prospettore Whelgar, agli scavi delle ⟦Wetlands=Paludi Grigie⟧.", "Raccogli un pezzo spezzato dell'automa di roccia. Ha una consistenza diversa da qualsiasi cosa tu abbia mai toccato, un materiale composito di natura sconosciuta. Di certo è più \"congegno\" che \"rottame\".\n\nForse il prospettore Whelgar in persona, ai suoi scavi, potrà dirti qualcosa di utile sulla reliquia.", nil, nil, 0x66a19050, 0x25ed1b64, 0x09d52652, nil, nil, "...mm" },
  [95816] = { "Iscrivimi!", "Porta il modulo compilato a Elaine Compton, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧.", "Salve, stimat<o/a> artigian<o/a>!\n\nCompilando questo modulo otterrai un permesso non esclusivo, revocabile e giuridicamente limitato di esporre insegne pubblicitarie per le tue professioni in tutta Azeroth!\n\nUna volta compilato, portalo al coordinatore dei contratti della filiale locale dell'Azeroth Commerce Authority per avviare la pratica.\n\nBuon lavoro!", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95817] = { nil, "Incontra Rotgath Stonebeard vicino alla ⟦Great Forge=Grande Forgia⟧, a ⟦Ironforge=Forgiardente⟧.", "Hai mai conosciuto Rotgath Stonebeard? È un fabbro nanico di ⟦Ironforge=Forgiardente⟧. Non è il tipo più loquace in circolazione, ma è sempre affidabile. Ci rivolgiamo spesso a lui quando ci servono grandi quantità di lavori dal disegno semplice, quelli che Stondry è troppo orgoglioso per accettare di persona.\n\nI suoi tempi di consegna sono eccellenti, soprattutto quando si tratta di aiutare nuovi artigiani ad avviare la propria bottega. Non affiderei a nessun altro la realizzazione rapida della tua insegna. Digli che ti mando io, se ti crea problemi!", nil, nil, 0xcc87f187, 0x29aa8c0c, 0x265b4cd5, nil, nil, "e..mm" },
  [95818] = { "Un lavoretto veloce", "Porta i materiali richiesti a Rotgath Stonebeard, vicino alla ⟦Great Forge=Grande Forgia⟧, a ⟦Ironforge=Forgiardente⟧.", "Possiamo sistemarti e rimetterti in strada in un attimo, purché tu abbia i materiali a portata di mano! Ci serviranno $N1 Lingotti di Mithril e $N2 ⟦Heavy Leather=Cuoio Pesante⟧. Di solito servono anche altri metalli e roba simile, ma ho qualche avanzo che occupa spazio e che possiamo usare per quei pezzi in più.\n\nAh, come favore personale, ti chiederò anche $N3 Goldthorn. Mia moglie conosce un'ottima ricetta per il tè e vorrei farle una sorpresa. Consideralo il tuo pagamento!", nil, nil, 0xae19085c, 0x93f08152, 0x8ce5bacd, nil, nil, "...mm" },
  [95819] = { "Iscrivimi!", "Porta il modulo compilato a Jornah, nelle ⟦The Barrens=Savane⟧.", "Salve, stimat<o/a> artigian<o/a>!\n\nCompilando questo modulo otterrai un permesso non esclusivo, revocabile e giuridicamente limitato di esporre insegne pubblicitarie per le tue professioni in tutta Azeroth!\n\nUna volta compilato, portalo al coordinatore dei contratti della Durotar Supply & Logistics della tua zona per avviare la pratica.\n\nBuon lavoro!", nil, nil, 0xe71188a6, 0x73fcb0bd, 0xb6355654, nil, nil, "...mm" },
  [95883] = { "L'anima tormentata", "Raccogli una Tortured Soul dai non morti vicini, alla ⟦Beren's Peril=Grotta di Beren⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "<I preparativi per un rituale allestito in fretta sono ammucchiati senza cerimonie sull'altare. Secondo il frammento di biglietto, è stato raccolto tutto. Mancano solo l'offerta di sangue e l'anima tormentata.\n\nI non morti attorno a te sembrano abbastanza tormentati. Potrebbero avere ciò che cerchi.>", "<La pietra delle offerte è minacciosamente immobile.>", "<In presenza della pietra delle offerte, l'anima tormentata sprigiona un'energia immonda.\n\nSembra che tu sia più vicin<o/a> a compiere il rituale.>", 0xb60b70e3, 0x0d080853, 0x972297ea, 0x03dfcb1a, 0x2d800f13, "....." },
  [95884] = { "La pietra delle offerte", "Trova la pietra delle offerte alla ⟦Beren's Peril=Grotta di Beren⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧.", "<Il frammento di biglietto è quasi tutto illeggibile. Ciò che si legge ancora, però, sono appunti sui preparativi per un'offerta.\n\nVi si menzionano una pietra delle offerte e un rituale.\n\nForse puoi trovare questa pietra delle offerte qui vicino.>", nil, "<Strani strumenti e oggetti ingombrano la superficie ruvida della pietra.\n\nQuesta è di certo la pietra delle offerte menzionata nel biglietto.>", 0xa6de587b, 0x975b0b28, 0x838aeea9, nil, 0xaa91f891, "...m." },
  [95885] = { "L'offerta di sangue", "Usa la Tortured Soul per compiere un'offerta di sangue alla pietra delle offerte, nella ⟦Beren's Peril=Grotta di Beren⟧.", "<Ora manca solo l'offerta di sangue.\n\nIl frammento di biglietto parlava di un \"sacrificio volontario\".\n\nUn intenso senso di terrore ti pervade.>", "<La pietra delle offerte è minacciosamente immobile.>", "<Ora la pietra delle offerte è inerte. Sembra che il tuo rituale l'abbia prosciugata del suo potere. A quale scopo, non lo sai, ma ormai è finita.\n\nLa pietra ruvida si crepa e si sgretola, ormai priva di scopo.\n\nQualcosa luccica tra i resti...>", 0x3785a093, 0x7d15beec, 0xb34b8754, 0x03dfcb1a, 0x73aa5f70, "....." },
  [95981] = { "Sorvegliare le strade", "Uccidi $N1 Dalaran Wizard e $N2 Dalaran Watcher per il Sacerdote dell'Ombra Allister, alla ⟦Sepulcher=Mausolea⟧.", "Togliere loro i pendenti è solo il primo passo. Se il Kirin Tor sta davvero spedendo da Dalaran un flusso costante di reliquie, dobbiamo fermarli alla fonte.\n\nCerca i maghi e i guardiani di Dalaran lungo le strade attorno a ⟦Ambermill=Mulino d'Ambra⟧. La loro presenza ha permesso per troppo tempo il libero passaggio attraverso i nostri confini. Se riusciamo a sfoltirne le fila, questi pendenti dovrebbero smettere di arrivare nella ⟦Silverpine Forest=Selva Pinargento⟧ fin dall'inizio.", nil, "Da quando è caduta la barriera attorno a Dalaran, il Kirin Tor tiene le strade in una morsa mortale. Hanno paura di qualcosa, questo è certo.\n\nPer ora, però, il perché non ha importanza.", 0xda0a241c, 0x94f2addc, 0x6d26148a, nil, 0xf9405a42, "...m." },
  [95998] = { "La vita all'aria aperta", "Siediti vicino al Sam's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Be', salve, {class}. Si vede che hai l'aria dell'avventuriero. Buon per te. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nIl mondo là fuori è grande e vasto, e per farcela dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma credo di poterti insegnare un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere? Ti insegneranno anche come costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xd61f22e7, 0xd463b94a, nil, 0x1938d14a, "...m." },
  [95999] = { "RICERCATO: Incinerator Gar'im", "Consegna il Broken Staff of Incinerator Gar'im al magistrato Solomon a ⟦Lakeshire=Borgolago⟧.", "Ricercato! Incinerator Gar'im, capo di un'incursione di orchi nella ⟦Render's Valley=Valle di Rend⟧. Si sospetta che collabori con i ⟦Blackrock=Roccianera⟧ del ⟦Stonewatch Keep=Mastio di Guardamasso⟧.\n\nAttenzione a Incinerator Gar'im. Lui e i suoi incantatori dell'ombra sono estremamente pericolosi. Una generosa ricompensa andrà a qualunque anima coraggiosa sappia consegnare al magistrato Solomon la prova della morte di Incinerator Gar'im.", "Che cos'hai lì, {race}?", "Ottimo lavoro, {name}! Incinerator Gar'im si preparava a rafforzare le difese del ⟦Stonewatch Keep=Mastio di Guardamasso⟧. Con questa vittoria, potremmo ancora riuscire a riconquistare il mastio!", 0xfbb45123, 0x39291674, 0x96bd3b4a, 0x46dc827d, 0xaf05c26e, "....." },
})
